function creerFilePriorite() {
  const heap = [];

  function _swap(i, j) {
    [heap[i], heap[j]] = [heap[j], heap[i]];
  }

  function _bubbleUp(index) {
    while (index > 0) {
      const parentIndex = Math.floor((index - 1) / 2);
      if (heap[parentIndex].priorite <= heap[index].priorite) break;
      _swap(parentIndex, index);
      index = parentIndex;
    }
  }

  function _bubbleDown(index) {
    const lastIndex = heap.length - 1;
    while (true) {
      let smallest = index;
      const left = 2 * index + 1;
      const right = 2 * index + 2;

      if (left <= lastIndex && heap[left].priorite < heap[smallest].priorite) {
        smallest = left;
      }
      if (right <= lastIndex && heap[right].priorite < heap[smallest].priorite) {
        smallest = right;
      }
      if (smallest === index) break;
      _swap(index, smallest);
      index = smallest;
    }
  }

  return {
    enqueue(val, priorite) {
      heap.push({ val, priorite });
      _bubbleUp(heap.length - 1);
    },
    dequeue() {
      if (heap.length === 0) return undefined;
      const min = heap[0];
      const end = heap.pop();
      if (heap.length > 0) {
        heap[0] = end;
        _bubbleDown(0);
      }
      return min.val;
    },
    taille() {
      return heap.length;
    }
  };
}
