function creerProxy(cible, gestionnaire) {
  const proxy = {};
  // Define getters/setters for all existing own properties of cible
  for (const key of Object.keys(cible)) {
    Object.defineProperty(proxy, key, {
      get() {
        return gestionnaire.get(cible, key);
      },
      set(value) {
        return gestionnaire.set(cible, key, value);
      },
      enumerable: true,
      configurable: true
    });
  }
  // For properties added later, we cannot intercept without Proxy.
  // This manual implementation only covers properties present at creation time.
  return proxy;
}
