function creerSubject() {
  const subscribers = [];
  let terminated = false;
  let terminationType = null; // 'complete' or 'error'
  let terminationValue = null;

  function notify(observer, type, value) {
    if (observer && typeof observer[type] === 'function') {
      try {
        observer[type](value);
      } catch (e) {
        // ignore errors in subscriber
      }
    }
  }

  return {
    next(val) {
      if (terminated) return;
      subscribers.forEach(obs => notify(obs, 'next', val));
    },
    error(err) {
      if (terminated) return;
      terminated = true;
      terminationType = 'error';
      terminationValue = err;
      subscribers.forEach(obs => notify(obs, 'error', err));
      subscribers.length = 0;
    },
    complete() {
      if (terminated) return;
      terminated = true;
      terminationType = 'complete';
      subscribers.forEach(obs => notify(obs, 'complete'));
      subscribers.length = 0;
    },
    subscribe(observer) {
      if (terminated) {
        if (terminationType === 'error') {
          notify(observer, 'error', terminationValue);
        } else {
          notify(observer, 'complete');
        }
        return { unsubscribe: () => {} };
      }
      subscribers.push(observer);
      return {
        unsubscribe() {
          const idx = subscribers.indexOf(observer);
          if (idx !== -1) subscribers.splice(idx, 1);
