```javascript
function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let state = 'closed'; // 'closed', 'open', 'half-open'
  let failureCount = 0;
  let lastFailureTime = 0;
  let halfOpenAttempt = false;

  async function execute(...args) {
    if (state === 'open') {
      const now = Date.now();
      if (now - lastFailureTime >= delaiResetMs) {
        state = 'half-open';
        halfOpenAttempt = false;
      } else {
        throw new Error('Circuit breaker is open');
      }
    }

    if (state === 'half-open') {
      if (halfOpenAttempt) {
        throw new Error('Circuit breaker is half-open and a test request is already in progress');
      }
      halfOpenAttempt = true;
    }

    try {
      const result = await fn(...args);
      onSuccess();
      return result;
    } catch (error) {
      onFailure();
      throw error;
    }
  }

  function onSuccess() {
    failureCount = 0;
    if (state === 'half-open') {
      state = 'closed';
    }
    halfOpenAttempt = false;
  }

  function onFailure() {
    failureCount++;
    lastFailureTime = Date.now();
    if (state === 'half-open') {
      state = 'open';
      halfOpenAttempt = false;
    } else if (state === 'closed' && failureCount >= seuil) {
      state = 'open';
    }
  }

  return execute;
}
```

