class LRUCache {
  constructor(capacite) {
    this.capacite = capacite;
    this.cache = new Map(); // key -> { value, prev, next }
    // Dummy head and tail for doubly linked list
    this.head = { prev: null, next: null };
    this.tail = { prev: null, next: null };
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  // Remove node from linked list
  _remove(node) {
    const prev = node.prev;
    const next = node.next;
    prev.next = next;
    next.prev = prev;
  }

  // Add node right after head (most recently used)
  _addToHead(node) {
    node.next = this.head.next;
    node.prev = this.head;
    this.head.next.prev = node;
    this.head.next = node;
  }

  get(cle) {
    if (!this.cache.has(cle)) return -1;
    const node = this.cache.get(cle);
    // Move to head (most recently used)
    this._remove(node);
    this._addToHead(node);
    return node.value;
  }

  put(cle, valeur) {
    if (this.cache.has(cle)) {
      const node = this.cache.get(cle);
      node.value = valeur;
      this._remove(node);
      this._addToHead(node);
      return;
    }

    if (this.cache.size >= this.capacite) {
      // Evict LRU (node before tail)
      const lru = this.tail.prev;
      this._remove(lru);
      this.cache.delete(lru.key);
    }

    const newNode = { key: cle, value: valeur, prev: null, next: null };
    this.cache.set(cle, newNode);
    this._addToHead(newNode);
  }
}
