function trier_tableau(arr) {
  // QuickSort implementation without using Array.prototype.sort()
  if (arr.length <= 1) return arr.slice();

  const pivot = arr[Math.floor(arr.length / 2)];
  const left = [];
  const right = [];
  const equal = [];

  for (const num of arr) {
    if (num < pivot) left.push(num);
    else if (num > pivot) right.push(num);
    else equal.push(num);
  }

  return [...trier_tableau(left), ...equal, ...trier_tableau(right)];
}
