function evaluerExpression(expr) {
  // Remove whitespace
  const tokens = expr.replace(/\s+/g, '');
  let pos = 0;

  function parseExpression() {
    let node = parseTerm();
    while (pos < tokens.length) {
      if (tokens[pos] === '+') {
        pos++;
        node = { type: '+', left: node, right: parseTerm() };
      } else if (tokens[pos] === '-') {
        pos++;
        node = { type: '-', left: node, right: parseTerm() };
      } else {
        break;
      }
    }
    return node;
  }

  function parseTerm() {
    let node = parseFactor();
    while (pos < tokens.length) {
      if (tokens[pos] === '*') {
        pos++;
        node = { type: '*', left: node, right: parseFactor() };
      } else if (tokens[pos] === '/') {
        pos++;
        node = { type: '/', left: node, right: parseFactor() };
      } else {
        break;
      }
    }
    return node;
  }

  function parseFactor() {
    if (tokens[pos] === '(') {
      pos++;
      const node = parseExpression();
      if (tokens[pos] !== ')') throw new Error('Mismatched parentheses');
      pos++;
      return node;
    }
    // Number (including negative)
    let start = pos;
    if (tokens[pos] === '-') pos++; // unary minus handled as part of number
    while (pos < tokens.length && /[\d.]/.test(tokens[pos])) pos++;
    const numStr = tokens.slice(start, pos);
    if (numStr === '' || numStr === '-') throw new Error('Invalid number');
    return { type: 'num', value: parseFloat(numStr) };
  }

  const ast = parseExpression();
  if (pos !== tokens.length) throw new Error('Unexpected characters');

  function evaluate(node) {
    if (node.type === 'num') return node.value;
    const left = evaluate(node.left);
    const right = evaluate(node.right);
    switch (node.type) {
      case '+': return left + right;
      case '-': return left - right;
      case '*': return left * right;
      case '/': return left / right;
    }
  }

  return evaluate(ast);
}
