function dijkstra(graphe, depart) {
  const distances = {};
  const visited = new Set();
  const nodes = new Set(Object.keys(graphe));
  // Include nodes that might only appear as targets
  for (const node in graphe) {
    for (const neighbor in graphe[node]) {
      nodes.add(neighbor);
    }
  }
  for (const node of nodes) {
    distances[node] = Infinity;
  }
  distances[depart] = 0;

  // Simple priority queue using array (since graph size is moderate)
  // For better performance, a min-heap could be used.
  const queue = [...nodes];

  while (queue.length > 0) {
    // Find unvisited node with smallest distance
    let minNode = null;
    let minDist = Infinity;
    for (const node of queue) {
      if (!visited.has(node) && distances[node] < minDist) {
        minDist = distances[node];
        minNode = node;
      }
    }
    if (minNode === null) break; // remaining nodes are unreachable
    visited.add(minNode);
    // Remove from queue
    const idx = queue.indexOf(minNode);
    if (idx !== -1) queue.splice(idx, 1);

    const neighbors = graphe[minNode] || {};
    for (const neighbor in neighbors) {
      const alt = distances[minNode] + neighbors[neighbor];
      if (alt < distances[neighbor]) {
        distances[neighbor] = alt;
      }
    }
  }

  return distances;
}
